out = []
for tid, level, display, aliases, sense, short, other in T:
    t = {"id": "rsc_" + tid, "level": level, "display": display, "aliases": aliases, "sense": sense, "short": short}
    if other:
        t["other"] = other
    out.append(t)
p = Path(__file__).resolve().parent.parent / "parts/09_research_gaps.json"
p.write_text("[\n" + ",\n".join(" " + json.dumps(t, ensure_ascii=False) for t in out) + "\n]\n")
